const topics = [
  {
    category: 'Soil Moisture & Root Rot',
    focus: 'Kenapa pokok cili layu waktu petang walaupun media basah lencun',
    fact: 'Bila tanah terlebih basah berterusan >6 jam, akar lemas sebab ketiadaan oksigen. Akar reput tak mampu pam air naik ke daun, jadi pokok layu macam kehausan.'
  },
  {
    category: 'Baja & EC Panas Terik',
    focus: 'Silap besar siram baja pekat (EC tinggi) waktu panas tengah hari',
    fact: 'Waktu matahari terik, kadar sejatan (transpirasi) tinggi gila. Pokok cuma nak sedut molekul air H2O, bukan garam baja. Siram baja pekat masa panas buat sel akar dehidrasi & daun terbakar.'
  },
  {
    category: 'Pest - Kutu Trip & Hama',
    focus: 'Tanda awal pucuk cili berkedut kerinting sebelum terlambat',
    fact: 'Kutu trip hisap cecair sel pucuk muda masa daun sebesar kuman. Bila daun dah kembang & kerinting mangkuk, racun serangga dah kurang berkesan sebab populasi dah merebak.'
  },
  {
    category: 'IoT Sensor ROI',
    focus: 'Pelaburan sensor IoT RM200 vs risiko rugi tuaian RM5,000 akibat pam mati',
    fact: 'Kerosakan pam fertigasi atau paip tersumbat yang lambat dikesan 24 jam boleh matikan ratusan polibeg serentak dalam fasa berbuah lebat.'
  },
  {
    category: 'Cocopeat & Tannin',
    focus: 'Bahaya tanam terus dalam sabut kelapa (cocopeat) baru beli tanpa cuci',
    fact: 'Cocopeat mentah ada kandungan garam sodium & tannin yang tinggi. Kalau tak basuh sampai bacaan EC < 0.5, anak benih jadi kerdil & daun bawah mula menguning.'
  },
  {
    category: 'Kalsium & Bunga Gugur',
    focus: 'Punca putik cili / tomato hitam di bahagian bontot (Blossom End Rot)',
    fact: 'Kekurangan kalsium bukan selalu sebab baja tak cukup, tapi sebab siraman tak sekata. Kalsium bergerak ikut aliran air transpirasi ke buah.'
  },
  {
    category: 'pH Media & Nutrisi',
    focus: 'Kenapa daun pokok kuning walaupun dah tabur macam-macam baja',
    fact: 'Bila pH media terlalu berasid (< 5.5), akar pokok terkunci (nutrient lockout). Pokok tak boleh serap Nitrogen & Magnesium walaupun baja bertimbun dalam pasu.'
  },
  {
    category: 'Siraman Pagi vs Malam',
    focus: 'Mitos siram pokok waktu malam buat kulat merebak',
    fact: 'Siram lewat malam buat daun basah sepanjang malam tanpa angin, mengundang spora kulat antraknos. Waktu siraman emas adalah antara 7.00 - 8.30 pagi.'
  }
];

const selected = topics[Math.floor(Math.random() * topics.length)];
// Anti-bot jitter: random delay between 20 to 120 seconds
const jitter = Math.floor(Math.random() * (120 - 20 + 1)) + 20;

return {
  json: {
    category: selected.category,
    focus: selected.focus,
    fact: selected.fact,
    jitterSeconds: jitter,
    timestamp: new Date().toISOString()
  }
};

